        "type": "(options: ToastOptions) => () => void",
        "description": "Show a toast notification. Returns a dismiss function. Options include body (ReactNode), type (\"info\" | \"error\"), isAutoHide, autoHideDuration, endContent, uniqueID, and collisionBehavior."
      }
    ],
    "usage": {
      "description": "Hook for showing toast notifications from anywhere in your component tree. Returns a function that accepts toast options and shows the notification. Works automatically with LayerProvider or self-mounts a fallback viewport.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use for transient success/error feedback that does not require user action."
        },
        {
          "guidance": true,
          "description": "Set uniqueID to deduplicate toasts from rapid user actions."
        },
        {
          "guidance": false,
          "description": "Use for critical errors that require acknowledgment; use AlertDialog instead."
        },
        {
          "guidance": false,
          "description": "Call useToast in the same component that renders LayerProvider; it must be called from a child component inside the provider."
        }
      ]
